import {
  ElementRef,
  PLATFORM_ID,
  Directive,
  booleanAttribute,
  effect,
  inject,
  input,
  model,
  viewChild,
} from '@angular/core';
import { isPlatformBrowser } from '@angular/common';

export type AevkoOverlaySide = 'center' | 'top' | 'right' | 'bottom' | 'left';

@Directive()
export abstract class AevkoDialogBase {
  readonly title = input.required<string>();
  readonly description = input('');
  readonly open = model(false);
  readonly initialFocus = input('');
  readonly closeOnEscape = input(true, { transform: booleanAttribute });
  readonly closeOnBackdrop = input(true, { transform: booleanAttribute });
  readonly restoreFocus = input(true, { transform: booleanAttribute });
  readonly showCloseButton = input(true, { transform: booleanAttribute });
  readonly dialogRole = input<'dialog' | 'alertdialog'>('dialog');
  readonly side = input<AevkoOverlaySide>('center');
  protected readonly panel = viewChild<ElementRef<HTMLDialogElement>>('panel');
  private readonly browser = isPlatformBrowser(inject(PLATFORM_ID));
  private returnTarget: HTMLElement | null = null;

  protected constructor(
    private readonly triggerAttribute: string,
    private readonly closeAttribute: string,
  ) {
    effect(() => {
      const panel = this.panel()?.nativeElement;
      const shouldOpen = this.open();
      if (!this.browser || !panel) return;
      if (shouldOpen && !panel.open) {
        this.returnTarget = document.activeElement as HTMLElement | null;
        panel.showModal();
        this.focusInitial(panel);
      } else if (!shouldOpen && panel.open) {
        panel.close();
      }
    });
  }

  protected handleClick(event: MouseEvent): void {
    const target = event.target;
    if (!(target instanceof Element)) return;
    if (target.closest(`[${this.triggerAttribute}]`)) {
      this.open.set(true);
      return;
    }
    if (target.closest(`[${this.closeAttribute}]`)) this.open.set(false);
  }

  protected handleBackdrop(event: MouseEvent): void {
    if (this.closeOnBackdrop() && event.target === this.panel()?.nativeElement) {
      this.open.set(false);
    }
  }

  protected handleCancel(event: Event): void {
    if (!this.closeOnEscape()) {
      event.preventDefault();
      return;
    }
    this.open.set(false);
  }

  protected handleClose(): void {
    if (this.open()) this.open.set(false);
    if (this.restoreFocus()) this.returnTarget?.focus();
  }

  protected close(): void {
    this.open.set(false);
  }

  private focusInitial(panel: HTMLDialogElement): void {
    const selector = this.initialFocus().trim();
    const target = selector ? panel.querySelector<HTMLElement>(selector) : null;
    queueMicrotask(() => (target ?? panel.querySelector<HTMLElement>('[autofocus]'))?.focus());
  }
}

import { ChangeDetectionStrategy, Component } from '@angular/core';
import { AevkoDialogBase } from './dialog-base';

@Component({
  selector: 'aevko-dialog',
  standalone: true,
  templateUrl: './dialog.component.html',
  styleUrl: './dialog.component.css',
  changeDetection: ChangeDetectionStrategy.OnPush,
  host: { '(click)': 'handleClick($event)' },
})
export class AevkoDialog extends AevkoDialogBase {
  constructor() {
    super('aevkoDialogTrigger', 'aevkoDialogClose');
  }
}

:host {
  display: contents;
}
dialog {
  background: var(--aevko-surface, #fff);
  border: 1px solid var(--aevko-border, #d4d4d4);
  border-radius: 0;
  color: var(--aevko-foreground, #171717);
  inline-size: min(32rem, calc(100vw - 2rem));
  max-block-size: calc(100dvh - 2rem);
  margin: auto;
  padding: 0;
}
dialog::backdrop {
  background: rgb(0 0 0 / 0.56);
}
dialog[data-side='top'],
dialog[data-side='bottom'] {
  inline-size: 100vw;
  max-inline-size: none;
}
dialog[data-side='top'] {
  margin-block: 0 auto;
}
dialog[data-side='bottom'] {
  margin-block: auto 0;
}
dialog[data-side='left'],
dialog[data-side='right'] {
  block-size: 100dvh;
  max-block-size: none;
  margin-block: 0;
}
dialog[data-side='left'] {
  margin-inline: 0 auto;
}
dialog[data-side='right'] {
  margin-inline: 0 0;
}
header {
  align-items: start;
  border-block-end: 1px solid var(--aevko-border, #d4d4d4);
  display: flex;
  gap: 1rem;
  justify-content: space-between;
  padding: 1.25rem;
}
h2 {
  font: inherit;
  font-size: 1.125rem;
  font-weight: 650;
  margin: 0;
}
p {
  color: var(--aevko-muted-foreground, #666);
  margin: 0.375rem 0 0;
}
.content {
  overflow: auto;
  padding: 1.25rem;
}
.close {
  align-items: center;
  background: transparent;
  border: 0;
  color: inherit;
  display: inline-flex;
  justify-content: center;
  min-block-size: 2rem;
  min-inline-size: 2rem;
  padding: 0.375rem;
}
.close:hover {
  background: var(--aevko-muted, #f1f1f1);
}
.close:focus-visible {
  outline: 2px solid var(--aevko-ring, #a3a3a3);
  outline-offset: 2px;
}
.close svg {
  fill: none;
  block-size: 1rem;
  inline-size: 1rem;
  stroke: currentColor;
  stroke-linecap: round;
  stroke-width: 2;
}
@media (prefers-reduced-motion: no-preference) {
  dialog[open] {
    animation: aevko-dialog-in 140ms ease-out;
  }
}
@keyframes aevko-dialog-in {
  from {
    opacity: 0;
    transform: translateY(0.5rem);
  }
}
@media (prefers-color-scheme: dark) {
  dialog {
    --aevko-surface: #171717;
    --aevko-foreground: #f5f5f5;
    --aevko-border: #404040;
    --aevko-muted: #262626;
    --aevko-muted-foreground: #b3b3b3;
  }
}
